<template><view class="dates"><picker mode="date" :value="dates[0]" @change="set(0,$event)"><text>{{ dates[0] || '开始日期' }}</text></picker><text>—</text><picker mode="date" :value="dates[1]" @change="set(1,$event)"><text>{{ dates[1] || '结束日期' }}</text></picker></view></template>
<script>export default { props: { modelValue: { default: () => [] }, value: { default: () => [] } }, emits:['update:modelValue','input','change'], computed:{dates(){return this.modelValue?.length ? this.modelValue : this.value || []}}, methods:{set(i,e){let d=[...this.dates];d[i]=e.detail.value;this.$emit('update:modelValue',d);this.$emit('input',d);this.$emit('change',d)}} }</script>
<style scoped>.dates{display:flex;align-items:center;justify-content:space-between;padding:24rpx;background:white;border-radius:16rpx;color:#735449}</style>
